def VTask.memPartition : {α : Type u_1} -> (f : ℕ → Set α) -> ℕ → Set (Set α) :=
fun α f n =>
if n = 0 then
  {univ}
else
  let prev_partition := VTask.memPartition α f (n - 1);
  let rec aux (partition : Set (Set α)) : Set (Set α) :=
    match partition with
    | {} => {}
    | s :: ss =>
      let s_intersect_fn := s ∩ f (n - 1);
      let s_diff_fn := s \ f (n - 1);
      insert (insert s_intersect_fn s_diff_fn) (aux ss)
  aux prev_partition
